(75,	'Bundtekst',	'<p><a title=\"Send besked\" href=\"https://webshop.cloud-crm.dk/service\">Send online besked</a> <span style=\"color: #999;\">&nbsp;|&nbsp;</span> Tlf.: +45 73 11 56 00 &nbsp;<span style=\"color: #999;\">|&nbsp;</span> CVR/VAT: 36722339 <span style=\"color: #999;\">&nbsp;|&nbsp;</span> <a title=\"Sitemap\" href=\"https://webshop.cloud-crm.dk/sitemap\">Sitemap</a> <span style=\"color: #999;\">&nbsp;|&nbsp;</span> <a title=\"Producenter\" href=\"https://webshop.cloud-crm.dk/producentmap\">Producenter</a> <span style=\"color: #999;\">&nbsp;|&nbsp;</span><img style=\"vertical-align: bottom; width: 30px;\" src=\"https://webshop.cloud-crm.dk/images/design/dankortlogo.png\" alt=\"\" /> Cloud Router &copy; 2018</p>',	'',	NULL,	NULL,	NULL,	NULL,	'bundtekst',	1),
(32,	NULL,	'WiFi, WLAN bridge og Firewall Router produkter',	'Cloud Router, WLAN bridge, FWA, Radio link, WiFi bridge, WiFi bridges, trådløs bridge, WiFi butik, Wifi, Wimax, trådløst data, trådløst net, trådløst netværk, trådløsse, Meru, Meru networks, Ubiquiti networks, Mikrotik, Router OS, Router Board, Routerboard, routerboards, udendørs trådløst netværk, wifi netværk, Hotspot Internet, Trådløst hotspot, Trådløst Internet, 3G Internet, punkt til punkt, 802.11, 802.11n, 802.11a, wireless, wireless network, Colubris, HP trådløst netværk, Wifi netkort, Trådløst netkort, Access point ',	'Cloud Router',	NULL,	NULL,	NULL,	'meta',	1),
(57,	'Disse er farver til sortering2 tabellen<br>\r\nFunktion1 er lig tekstfarve i listetekst (under varenavn);<br>\r\nFunktion2 er lig baggrundsfarve på feltet;<br>\r\nFunktion3 er lig baggrundsfarve på feltet når musen føres hen over;<br>\r\nFunktion4 er lig tekstfarve i feltet;<br>\r\nFunktion5 er lig tekstfarve i feltet når musen føres hen over.',	'#4E4D40',	'',	'#FFFF99',	'#2B3856',	'#151B54',	NULL,	'sortering2_farver',	1),
