(21,	NULL,	'<p><span style=\"color: red; font-family: \'Verdana\',\'sans-serif\'; font-size: 8pt; mso-fareast-font-family: Calibri; mso-fareast-theme-font: minor-latin; mso-bidi-font-family: \'Times New Roman\'; mso-ansi-language: DA; mso-fareast-language: DA; mso-bidi-language: AR-SA; mso-bidi-font-size: 9.0pt;\"><strong>Forudbetaling</strong></span>, varerne afsendes n&aring;r betalingen er&nbsp;modtaget.&nbsp;</p>\r\n<p>Kvitteringen kan sendes til bogholderi&nbsp;for hurtigere ekspedition.</p>',	'<p>Efterkrav betaling:</p>\r\n<p>&nbsp;</p>',	'<p><span>Betaling med Dankort<span>&nbsp;&nbsp;<img style=\"vertical-align: bottom;\" src=\"https://webshop.cloud-crm.dk/images/design/dankortlogo.png\" alt=\"\" /></span></span></p>',	'<p>Ordren betales kontant ved afhentning. Kan ikke benyttes til en postordre.</p>',	'<p>Kontokunde - faktura betaling</p>',	NULL,	'step2_beskrivelser1',	1),
